rule.definition:
if(
  a!isNullOrEmpty(ri!recordData),
  #"SYSTEM_SYSRULES_httpResponse_v1"(
    statusCode: 400,
    headers: {
      #"SYSTEM_SYSRULES_httpHeader"(name: "Content-Type", value: "application/json")
    },
    body: #"SYSTEM_SYSRULES_toJson_v1"(
      a!map(
        success: false,
        error: "MISSING_PARAMETER",
        message: "recordData is required"
      )
    )
  ),
  a!localVariables(
    local!recordTypeUuid: ri!recordData.recordType,
    local!fieldData: cast(typeof(a!map()), ri!recordData.fields),
    if(
      or(
        a!isNullOrEmpty(local!recordTypeUuid),
        a!isNullOrEmpty(local!fieldData)
      ),
      #"SYSTEM_SYSRULES_httpResponse_v1"(
        statusCode: 400,
        headers: {
          #"SYSTEM_SYSRULES_httpHeader"(name: "Content-Type", value: "application/json")
        },
        body: #"SYSTEM_SYSRULES_toJson_v1"(
          a!map(
            success: false,
            error: "MISSING_PARAMETER",
            message: "recordData must contain recordType and fields"
          )
        )
      ),
      a!localVariables(
        local!properties: a!recordTypeProperties(
          recordType: eval(concat("recordType!{", local!recordTypeUuid, "}"))
        ),
        if(
          a!isNullOrEmpty(local!properties.recordType.fields),
          #"SYSTEM_SYSRULES_httpResponse_v1"(
            statusCode: 404,
            headers: {
              #"SYSTEM_SYSRULES_httpHeader"(name: "Content-Type", value: "application/json")
            },
            body: #"SYSTEM_SYSRULES_toJson_v1"(
              a!map(
                success: false,
                error: "RECORD_TYPE_NOT_FOUND",
                message: "No record type found for UUID: " & local!recordTypeUuid
              )
            )
          ),
          a!localVariables(
            local!fieldNames: a!keys(local!fieldData),
            local!record: eval(concat("recordType!{", local!recordTypeUuid, "}()")),
            local!fieldReferences: #"SYSTEM_SYSRULES_forEach"(
              items: local!fieldNames,
              expression: displayvalue(
                fv!item,
                local!properties.recordType.fields.name,
                local!properties.recordType.fields.reference,
                null
              )
            ),
            local!invalidFields: index(
              local!fieldNames,
              where(#"SYSTEM_SYSRULES_forEach"(items: local!fieldReferences, expression: isnull(fv!item))),
              {}
            ),
            if(
              length(local!invalidFields) > 0,
              #"SYSTEM_SYSRULES_httpResponse_v1"(
                statusCode: 400,
                headers: {
                  #"SYSTEM_SYSRULES_httpHeader"(name: "Content-Type", value: "application/json")
                },
                body: #"SYSTEM_SYSRULES_toJson_v1"(
                  a!map(
                    success: false,
                    error: "INVALID_FIELDS",
                    message: "Unknown field names: " & tostring(local!invalidFields)
                  )
                )
              ),
              a!localVariables(
                local!validRefs: reject(fn!isnull, local!fieldReferences),
                local!validValues: #"SYSTEM_SYSRULES_forEach"(
                  items: local!fieldNames,
                  expression: a!localVariables(
                    local!fieldType: displayvalue(
                      fv!item,
                      local!properties.recordType.fields.name,
                      local!properties.recordType.fields.type,
                      "Text"
                    ),
                    #"_a-0000efc0-b1bf-8000-9bbd-011c48011c48_59872"(
                      value: index(local!fieldData, fv!item, null),
                      fieldType: local!fieldType
                    )
                  )
                ),
                local!finalRecord: #"urn:appian:function:v1:a:update"(
                  local!record,
                  local!validRefs,
                  local!validValues
                ),
                #"SYSTEM_SYSRULES_writeRecords_v2"(
                  records: local!finalRecord,
                  onSuccess: #"SYSTEM_SYSRULES_httpResponse_v1"(
                    statusCode: 200,
                    headers: {
                      #"SYSTEM_SYSRULES_httpHeader"(name: "Content-Type", value: "application/json")
                    },
                    body: #"SYSTEM_SYSRULES_toJson_v1"(
                      a!map(
                        success: true,
                        recordsUpdated: fv!recordsUpdated
                      )
                    )
                  ),
                  onError: #"SYSTEM_SYSRULES_httpResponse_v1"(
                    statusCode: 500,
                    headers: {
                      #"SYSTEM_SYSRULES_httpHeader"(name: "Content-Type", value: "application/json")
                    },
                    body: #"SYSTEM_SYSRULES_toJson_v1"(
                      a!map(
                        success: false,
                        error: "WRITE_FAILED",
                        message: tostring(fv!error)
                      )
                    )
                  )
                )
              )
            )
          )
        )
      )
    )
  )
)
